Исправь следующий код так, чтобы для выражений в RPN был такой вывод:
rpn: 1 2 +, tuple: (1, 2, +), result = 3.0
rpn: 1 4 4 * -, tuple: (1, 4 4 *, -), result = -15.0
rpn: 10 2 / 4 4 * -, tuple: (10 2 /, 4 4 *, -), result = -11.0

public class Triple<T, V, K> {
    protected T v1;
    protected V v2;
    protected K v3;

    Triple(T v1, V v2, K v3) {
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    @Override
    public String toString() {
        return v1 + " " + v2 + " " + v3;
    }

    // вывод кортежа
    public String toStringList() {
        return "(" + v1 + ", " + v2 + ", " + v3 + ")";
    }
}

